"use strict";
const signup=document.createElement("button");signup.type="button";signup.textContent="Create my editor account";signup.className="button";
const help=document.createElement("p");help.textContent="First visit? Use bublooscientist2023@gmail.com, choose a password, then create your account and verify your email. Other addresses cannot edit this site.";
const login=document.querySelector("#login");login.append(help,signup);
login.elements.email.value="bublooscientist2023@gmail.com";
signup.onclick=async()=>{const email=login.elements.email.value.trim(),password=login.elements.password.value;const status=document.querySelector("#status");if(email.toLowerCase()!=="bublooscientist2023@gmail.com"){status.textContent="Please use the designated editor email.";return}if(password.length<12){status.textContent="Choose a password of at least 12 characters.";return}signup.disabled=true;try{const r=await fetch(window.SITE_CONFIG.supabaseUrl+"/auth/v1/signup",{method:"POST",headers:{apikey:window.SITE_CONFIG.publishableKey,"Content-Type":"application/json"},body:JSON.stringify({email,password})});if(!r.ok)throw Error();status.textContent="Check your inbox to verify your email, then return here and sign in. If the account already exists, use Sign in.";login.elements.password.value=""}catch{status.textContent="Account creation could not be completed. Try again later or use Supabase’s user dashboard."}finally{signup.disabled=false}};
